def calc_b_coeffs_new(x1, y1, x2, y2, z1, z2, sens):
    u0 = 4 * np.pi * 1e-7
    a = np.array([x1, y1, z1])
    b = np.array([x2, y2, z2])
    u = b - a
    v = sens - a

    cross = np.cross(u, v)

    b_1 = np.dot(v,u)/np.linalg.norm(v)
    b_2 = (np.linalg.norm(u)**2-np.dot(v,u))/np.linalg.norm(sens-b)

    return (u0/(4*np.pi))*(cross/(np.linalg.norm(cross))**2)*(b_1+b_2)


def calc_B(magsens_pos, leiter_arr, curr_list):
    B_ges = 0
    u0 = 4 * np.pi * 1e-7
    for i in range(len(leiter_arr)):
        for j in range(len(leiter_arr[i])):
            B_ges += curr_list[i]*calc_b_coeffs_new(*leiter_arr[i][j],magsens_pos)

    return B_ges

